AOD_GAMEMODE="survival"import("winconditions/aod.scar")import("winconditions/aod_abilities.scar")import("winconditions/aod_points.scar")import("winconditions/aod_survival_units.scar")SURVIVAL_WAVE_POINTS=0 SURVIVAL_LIVING_SQUADS={}SURVIVAL_SCORE_MULTIPLIER={1.0,0.9,0.8,0.7}function Mission_AOD_Start()if(not Event_IsAnyRunning())then Rule_RemoveMe()if(not SETTINGS.IsInitialized()or#(SETTINGS.GetSetting("AI_PATHS"))==0)then return end SPAWN_TEST_DUMMY_ENTITY=Entity_Create(BP_GetEntityBlueprint("assault_engineer_mp"),AIPlayer1,World_Pos(0,0,0),World_Pos(0,0,0))SURVIVAL_WAVE_POINTS=SETTINGS.GetSetting("SURVIVAL")["starting_points"]Game_FadeToBlack(FADE_OUT,0)Game_FadeToBlack(FADE_IN,0.5)SETTINGS.GetSetting("DIFFICULTY")["wave"]["veterancy"]=0
