local attackerSquads=SGroup_CreateIfNotFound("temp_attacker_squads")local attackerEntities=EGroup_CreateIfNotFound("temp_attacker_entities")Squad_GetLastAttacker(squad,attackerSquads)Squad_GetLastEntityAttacker(squad,attackerEntities)if(SGroup_CountSpawned(attackerSquads)>0)then for i=1,SGroup_CountSpawned(attackerSquads)do local attackerSquad=SGroup_GetSpawnedSquadAt(attackerSquads,i)if(not World_OwnsSquad(attackerSquad))then local owner=Squad_GetPlayerOwner(attackerSquad)AOD_Points_IncreaseTeamScore(owner,squad_points_players)end end elseif(EGroup_CountSpawned(attackerEntities)>0)then for i=1,EGroup_CountSpawned(attackerEntities)do local attackerEntity=EGroup_GetSpawnedEntityAt(attackerEntities,i)if(not World_OwnsEntity(attackerEntity))then local owner=Entity_GetPlayerOwner(attackerEntity)AOD_Points_IncreaseTeamScore(owner,squad_points_players)end end end SGroup_Destroy(attackerSquads)EGroup_Destroy(attackerEntities)
AOD_Points_IncreaseTotalScore(squad_points)table.remove(SURVIVAL_LIVING_SQUADS,i)local show_objective=math.floor(points_before/1000,0)<math.floor(AOD_Points_GetTotalScore()/1000,0)if(show_objective)then AOD_Points_UpdateScoreObjective(true,math.floor(AOD_Points_GetTotalScore()/1000,0)*1000)else AOD_Points_UpdateScoreObjective(false)end UI_CreatePositionKickerMessage(Game_GetLocalPlayer(),Squad_GetPosition(squad),Loc_ConvertNumber(round(squadInfo["points"],0)))break end end Profiler_EndFunction("CheckKilledAISquads")end function _OverrunDestroySquad(groupid,itemindex,itemid)local squadId=Squad_GetGameID(itemid)if(SGroup_ContainsSquad(CURRENT_WAVE_GROUP,squadId))then if(CRITICALS_NON_FAIL~=nil)then for i,critical in ipairs(CRITICALS_NON_FAIL)do if(Squad_HasCritical(itemid,critical))then return end end end for i,squad in ipairs(SURVIVAL_LIVING_SQUADS)do if(squad["id"]==squadId)then table.remove(SURVIVAL_LIVING_SQUADS,i)break end end ENDING_LAST_UNIT_LOCATION=Squad_GetPosition(itemid)Squad_Destroy(itemid)UNITS_PASSED_COUNTER=UNITS_PASSED_COUNTER+1 end end function AOD_Ending()local playerPointsString1=""local playerPointsString2=""local humanPlayers=Team_GetPlayers(0)local playerCount=#humanPlayers for i,player in ipairs(humanPlayers)do local playerName=Player_GetDisplayName(player)[1]local playerPoints=round(AOD_Points_GetPlayerScore(player),0)if(i<=2)then playerPointsString1=playerPointsString1 .. playerName..": "..playerPoints.." - "else playerPointsString2=playerPointsString2 .. playerName..": "..playerPoints.." - "end end local summaryText=Loc_FormatText(Util_CreateLocId(1337019),AI_DIFFICULTY_LOCID)[1]summaryText=summaryText.." - "..Loc_FormatText(Util_CreateLocId(1337021),Loc_ConvertNumber(CURRENT_WAVE_NR))[1]summaryText=summaryText.." - "..Loc_FormatText(Util_CreateLocId(1337018),Loc_ConvertNumber(round(AOD_Points_GetTotalScore(),0)))[1]if(playerCount<=2)then Util_SubTextFade(Util_CreateLocString(summaryText),Util_CreateLocString(""),Util_CreateLocString(string.sub(playerPointsString1,0,-3)),1.0,60.0,1.0)
else Util_SubTextFade(Util_CreateLocString(summaryText),Util_CreateLocString(string.sub(playerPointsString1,0,-3)),Util_CreateLocString(string.sub(playerPointsString2,0,-3)),1.0,60.0,1.0)
end World_SetPlayerWin(AIPlayer1)GameOver(false)if(ENDING_LAST_UNIT_LOCATION~=nil)then Camera_MoveTo(ENDING_LAST_UNIT_LOCATION,true,0.5)end end function _SpawnWaves()Profiler_StartFunction("_SpawnWaves")if(not WAVE_SPAWNING and Timer_GetRemaining(1)<=0.0)then if(not WAITING_FOR_NEXT_WAVE and CURRENT_WAVE_NR>0)then local survival_settings=SETTINGS.GetSetting("SURVIVAL")local start_countdown=true if(survival_settings["wait_until_everybody_dead"]~=nil and survival_settings["wait_until_everybody_dead"])then if(SGroup_GetAvgHealth(CURRENT_WAVE_GROUP)>0.0)then start_countdown=false end end if(start_countdown)then WAITING_FOR_NEXT_WAVE=true local delay=SETTINGS.GetSetting("WAVE_DEFAULT_INTERVAL")if(survival_settings["delay_after_wave"]~=nil)then delay=survival_settings["delay_after_wave"]end if(survival_settings["wave_pause_interval"]~=nil and survival_settings["wave_pause_interval"]>0 and survival_settings["wave_pause_length"]~=nil and(CURRENT_WAVE_NR%survival_settings["wave_pause_interval"]==0))then delay=delay+survival_settings["wave_pause_length"]Util_ShowMissionTitle(Util_CreateLocId(1337028),1.0,5.0,1.0)
end Timer_Start(1,delay)if(not Objective_IsStarted(OBJECTIVES["next_wave"]))then Objective_Start(OBJECTIVES['next_wave'],true)end Objective_Show(OBJECTIVES['next_wave'],true)Objective_StartTimer(OBJECTIVES['next_wave'],COUNT_DOWN,delay)if(survival_settings~=nil)then if(survival_settings["bomb_friendly_squads_on_route"]~=nil)then BOMB_FRIENDLY_SQUADS_ON_ROUTE=BOMB_FRIENDLY_SQUADS_ON_ROUTE and Util_GetDifficultyValue(survival_settings["bomb_friendly_squads_on_route"])end if(survival_settings["hurt_friendly_squads_on_route"]~=nil)then HURT_FRIENDLY_SQUADS_ON_ROUTE=HURT_FRIENDLY_SQUADS_ON_ROUTE and Util_GetDifficultyValue(survival_settings["hurt_friendly_squads_on_route"])end if(survival_settings["hurt_moving_friendly_squads_on_route"]~=nil)then HURT_MOVING_FRIENDLY_SQUADS_ON_ROUTE=HURT_MOVING_FRIENDLY_SQUADS_ON_ROUTE and Util_GetDifficultyValue(survival_settings["hurt_moving_friendly_squads_on_route"])end end end else Objective_Show(OBJECTIVES['next_wave'],false)Objective_Complete(OBJECTIVES['countdown'],false)WAITING_FOR_NEXT_WAVE=false WAVE_DO_SPAWN=true end end SpawnWave()Profiler_EndFunction("_SpawnWaves")end function ResetWave()Timer_Start(0,0)local survival_settings=SETTINGS.GetSetting("SURVIVAL")BOMB_FRIENDLY_SQUADS_ON_ROUTE=false HURT_FRIENDLY_SQUADS_ON_ROUTE=false HURT_MOVING_FRIENDLY_SQUADS_ON_ROUTE=false if(survival_settings["bomb_friendly_squads_on_route"]~=nil and survival_settings["bomb_friendly_squads_on_route"])then BOMB_FRIENDLY_SQUADS_ON_ROUTE=true elseif(survival_settings["hurt_friendly_squads_on_route"]~=nil and survival_settings["hurt_friendly_squads_on_route"])then HURT_FRIENDLY_SQUADS_ON_ROUTE=true elseif(survival_settings["hurt_moving_friendly_squads_on_route"]~=nil and survival_settings["hurt_moving_friendly_squads_on_route"])then HURT_MOVING_FRIENDLY_SQUADS_ON_ROUTE=true end KILL_FRIENDLY_ENTITIES_ON_ROUTE=false if(survival_settings["kill_friendly_entities_on_route"]~=nil and survival_settings["kill_friendly_entities_on_route"])then KILL_FRIENDLY_ENTITIES_ON_ROUTE=true end BOMB_FRIENDLY_ENTITIES_ON_ROUTE=false if(survival_settings["bomb_friendly_entities_on_route"]~=nil and survival_settings["bomb_friendly_entities_on_route"])then BOMB_FRIENDLY_ENTITIES_ON_ROUTE=true end Objective_UpdateText(OBJECTIVES["wave"],Loc_FormatText(Util_CreateLocId(1337021),Loc_ConvertNumber(CURRENT_WAVE_NR)),nil,true)
if(not Objective_IsStarted(OBJECTIVES["wave"]))then Objective_Start(OBJECTIVES["wave"],true)end end function SpawnWave()Profiler_StartFunction("SpawnWave")if(not WAVE_SPAWNING and WAVE_DO_SPAWN)then WAVE_DO_SPAWN=false CURRENT_WAVE_NR=CURRENT_WAVE_NR+1 SURVIVAL_WAVE_POINTS=SURVIVAL_WAVE_POINTS+(CURRENT_WAVE_NR-1)*SETTINGS.GetSetting("SURVIVAL")["points_multiplier_per_wave"]ResetWave()GenerateWaves()CURRENT_WAVE_TIMER=0 WAVE_SPAWNING=true end if(WAVE_SPAWNING)then if(Timer_GetRemaining(0)<=0.0)then spawning=false for i,wave in ipairs(CURRENT_WAVE)do delay=0 if(CURRENT_WAVE[i]["delay"]~=nil)then delay=CURRENT_WAVE[i]["delay"]end if(not CURRENT_WAVE[i]["spawning"]and not CURRENT_WAVE[i]["spawned"])then
CURRENT_WAVE[i]["spawning"]=true end if(CURRENT_WAVE[i]["spawning"]and CURRENT_WAVE[i]["counter"]<=wave["count"]and CURRENT_WAVE_TIMER>=(delay+(CURRENT_WAVE[i]["counter"]-1)*wave["interval"]))then CURRENT_WAVE[i]["counter"]=CURRENT_WAVE[i]["counter"]+1 spawned_squads=SpawnSquad(wave)if(spawned_squads~=nil)then for i,squad in ipairs(spawned_squads)do table.insert(SURVIVAL_LIVING_SQUADS,{["id"]=squad,["points"]=wave["points"]})Rule_AddSquadEvent(CheckKilledAISquads,Squad_FromWorldID(squad),GE_SquadKilled)end end if(CURRENT_WAVE[i]["counter"]>wave["count"])then CURRENT_WAVE[i]["spawning"]=false CURRENT_WAVE[i]["spawned"]=true end end if(CURRENT_WAVE[i]["spawning"])then spawning=true end end if(not spawning)then WAVE_SPAWNING=false end end end Profiler_EndFunction("SpawnWave")end function FindMostExpensiveUnit(max_points,movement_type)local mostExpensiveUnit=nil for i,faction in pairs(SETTINGS.GetSetting("SURVIVAL")["factions"])do if(SURVIVAL_UNIT_LIST[faction]~=nil)then for j,unit in ipairs(SURVIVAL_UNIT_LIST[faction])do if(unit["points"]<=max_points)then if(unit["movement_type"]==nil or unit["movement_type"]==movement_type)then if(mostExpensiveUnit==nil or unit["points"]>mostExpensiveUnit["points"])then mostExpensiveUnit=unit end end end end end end return mostExpensiveUnit end function PrecacheUnits(max_points,movement_type,most_expensive_unit_cost)local units={}local spawn_chance=most_expensive_unit_cost/SETTINGS.GetSetting("SURVIVAL")["expensive_unit_spawn_chance_multiplier"]for i,faction in pairs(SETTINGS.GetSetting("SURVIVAL")["factions"])do if(SURVIVAL_UNIT_LIST[faction]~=nil)then for j,unit in ipairs(SURVIVAL_UNIT_LIST[faction])do Profiler_NumberInc("GenerateWaves (unit lookup)")if(unit["points"]<=max_points)then if(unit["movement_type"]==nil or unit["movement_type"]==movement_type)then table.insert(units,unit)if(unit["points"]>spawn_chance)then for k=1,math.floor(unit["points"]/spawn_chance)-1 do table.insert(units,unit)end end end end end else Util_ShowWarning("Trying to spawn a unit from faction "..faction..", which doesn't exist")end end return units end function UpdatePrecachedUnits(precachedList,max_points)local index=1 while(index<=#precachedList)do if(precachedList[index]["points"]>max_points)then table.remove(precachedList,index)else index=index+1 end end return precachedList end function FindUnit(units)if(#units>0)then local random_index=World_GetRand(1,#units)return units[random_index]else return nil end end function FindPaths()local paths={}for index,path in ipairs(SETTINGS.GetSetting("AI_PATHS"))do if(path["path"]~=nil or path["target"]~=nil)then table.insert(paths,index)end end return paths end function FindItems(unit,points,movement_type)if(unit["items"]~=nil)then local items_affordable={}for index,item in ipairs(unit["items"])do Profiler_NumberInc("GenerateWaves (item lookup)")if(item["points"]<=points)then if(unit["movement_type"]==nil or unit["movement_type"]==movement_type)then table.insert(items_affordable,item)end end end if(#items_affordable>0)then for index,item in ipairs(items_affordable)do if(World_GetRand(1,#items_affordable*2)==1)then return item end end end end return nil end function FindUpgrade(unit,points,movement_type)if(unit["upgrades"]~=nil)then local items_affordable={}for index,item in ipairs(unit["upgrades"])do Profiler_NumberInc("GenerateWaves (upgrade lookup)")if(item["points"]<=points)then if(unit["movement_type"]==nil or unit["movement_type"]==movement_type)then table.insert(items_affordable,item)end end end if(#items_affordable>0)then for index,item in ipairs(items_affordable)do if(World_GetRand(1,#items_affordable*2)==1)then return item end end end end return nil end function GenerateModifiers(points,value,modifiers)Profiler_StartFunction("GenerateModifiers")modifiers=modifiers or{}local points_used=0 local possible_modifiers={{["name"]="armor",["value"]=1.05,["points"]=0.3*value},{["name"]="speed",["value"]=1.1,["points"]=0.3*value},{["name"]="received_damage",["value"]=0.8,["points"]=0.4*value},{["name"]="damage",["value"]=1.2,["points"]=0.4*value},{["name"]="weapon_reload",["value"]=0.9,["points"]=0.3*value},}modifiers["received_suppression"]=1.0+(CURRENT_WAVE_NR*-0.1)modifiers["received_damage"]=math.max(1.0+(CURRENT_WAVE_NR*-0.01),0.7)local random_number=World_GetRand(1,20)while(random_number<math.min(CURRENT_WAVE_NR*2,40))do local valid=false local chosen_modifier=nil local fail_count=0 while(not valid and fail_count<10)do valid=true local random_modifier=possible_modifiers[World_GetRand(1,#possible_modifiers)]if(random_modifier["name"]=="speed"and modifiers["speed"]~=nil and modifiers["speed"]>1.6)then valid=false elseif(random_modifier["name"]=="received_damage"and modifiers["received_damage"]~=nil and modifiers["received_damage"]<0.15)then valid=false elseif(random_modifier["name"]=="armor"and modifiers["armor"]~=nil and modifiers["armor"]>1.2)then valid=false elseif(random_modifier["name"]=="weapon_reload"and modifiers["weapon_reload"]~=nil and modifiers["weapon_reload"]<0.5)then valid=false else chosen_modifier=random_modifier end fail_count=fail_count+1 end if(chosen_modifier~=nil and points>chosen_modifier["points"])then if(modifiers[chosen_modifier["name"]]~=nil)then modifiers[chosen_modifier["name"]]=modifiers[chosen_modifier["name"]]*chosen_modifier["value"]else modifiers[chosen_modifier["name"]]=chosen_modifier["value"]end points_used=points_used+chosen_modifier["points"]else break end random_number=World_GetRand(1,43)end local points_increase=math.floor(points_used/(value*1.5))modifiers["veterancy"]=points_increase Profiler_EndFunction("GenerateModifiers")return{["points"]=points_used,["list"]=modifiers}end function GenerateWaves()CURRENT_WAVE={}local available_paths=FindPaths()local points_per_path=math.ceil(SURVIVAL_WAVE_POINTS/#available_paths)Profiler_NumberReset("GenerateWaves (unit lookup)")Profiler_NumberReset("GenerateWaves (item lookup)")Profiler_NumberReset("GenerateWaves (upgrade lookup)")for i,path_index in ipairs(available_paths)do local points=points_per_path local units_spawned=0 local path=SETTINGS.GetSetting("AI_PATHS")[path_index]local movement_type=path["movement_type"]local mostExpensiveUnit=FindMostExpensiveUnit(points,movement_type)local mostExpensiveUnitCost=1 if(mostExpensiveUnit~=nil)then mostExpensiveUnitCost=mostExpensiveUnit["points"]end local availableUnits=PrecacheUnits(points,movement_type,mostExpensiveUnitCost)while(points>=1)do availableUnits=UpdatePrecachedUnits(availableUnits,points)local unit=FindUnit(availableUnits)if(unit==nil)then break end local unit_points=unit["points"]points=points-unit["points"]local item={}local upgrade={}local random_item=FindItems(unit,points,movement_type)if(random_item~=nil)then points=points-random_item["points"]unit_points=unit_points+random_item["points"]item={random_item["blueprint"]}end local random_upgrade=FindUpgrade(unit,points,movement_type)if(random_upgrade~=nil)then points=points-random_upgrade["points"]unit_points=unit_points+random_upgrade["points"]upgrade={random_upgrade["blueprint"]}end local modifiers=GenerateModifiers(points,unit_points,unit["modifiers"])points=points-modifiers["points"]unit_points=unit_points+modifiers["points"]local delay=1 if(SETTINGS.GetSetting("SURVIVAL")["spawn_interval"]~=nil)then delay=units_spawned*SETTINGS.GetSetting("SURVIVAL")["spawn_interval"]else delay=unit["points"]*1.2+units_spawned*1.2+World_GetRand(1,10)/10 end CURRENT_WAVE[#CURRENT_WAVE+1]={["type"]=unit["blueprint"],["upgrades"]=upgrade,["slots"]=item,["interval"]=2,["count"]=1,["counter"]=1,["spawns"]={path_index},["delay"]=delay,["modifiers"]=modifiers["list"],["spawning"]=false,["spawned"]=false,["points"]=unit_points}units_spawned=units_spawned+1 end end Profiler_Number("GenerateWaves (waves)",#CURRENT_WAVE)end
